import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  Easing,
} from '../remotionShim';
// [Start Google Fonts Loader]
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// [End Google Fonts Loader]



export type ConnectedNetworkProps = Record<string, any>;

const ConnectedNetwork: React.FC<ConnectedNetworkProps> = ({
  backgroundColor = "#111827",
  transparentBackground = false,
  durationInSeconds = 10,
  nodeColor = "#3B82F6",
  lineColor = "#60A5FA",
  titleColor = "#F3F4F6",
  nodeCount = 18,
  connectionDistance = 250,
  nodeSize = 8,
  titleText = "CORE TEAM",
  driftSpeed = 1.0,
}) => {
  useFontLoader(["Inter", "Montserrat"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Parse colors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Generate deterministic nodes in a spiral layout for "growing" feel
  const nodes = useMemo(() => {
    const cx = width / 2;
    const cy = height / 2;
    
    return new Array(nodeCount).fill(0).map((_, i) => {
      // Golden angle for organic spiral distribution
      const angle = i * 2.39996; // ~137.5 degrees in radians
      
      // Spiral radius calculation
      // Minimum radius to clear the central title element
      const minRadius = Math.min(width, height) * 0.15;
      const maxRadius = Math.min(width, height) * 0.45;
      const rStep = (maxRadius - minRadius) / Math.sqrt(nodeCount);
      const targetRadius = minRadius + rStep * Math.sqrt(i);

      // Deterministic pseudo-randomness for variation
      const seed = i * 789;
      const rSize = (random(seed) * 0.5) + 0.8; // 0.8 to 1.3
      const label = `USER-${String(i + 1).padStart(2, '0')}`;

      return { 
        id: i, 
        angle, 
        targetRadius, 
        sizeVar: rSize,
        label,
        cx,
        cy
      };
    });
  }, [nodeCount, width, height]);

  // Animation Sequence
  const expansionStartFrame = 15;

  // 1. Central Element (Title) Animation
  const titleScale = spring({
    frame,
    fps,
    config: { damping: 15, stiffness: 120 },
  });
  
  const titleOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  // 2. Nodes Animation (Expanding outward)
  const animatedNodes = nodes.map((node, i) => {
    const stagger = i * 2;
    const startFrame = expansionStartFrame + stagger;

    // Scale/Pop in
    const scale = spring({
      frame: frame - startFrame,
      fps,
      config: { damping: 14, stiffness: 90 },
    });

    // Expansion from center
    const expandProgress = interpolate(frame, [startFrame, startFrame + 45], [0, 1], {
      easing: Easing.out(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    // Orbital Drift (Slow rotation)
    const driftAngle = (frame * 0.005 * driftSpeed) + (i % 2 === 0 ? 0 : 0.05);
    
    const currentRadius = node.targetRadius * expandProgress;
    const currentAngle = node.angle + driftAngle;

    const x = node.cx + Math.cos(currentAngle) * currentRadius;
    const y = node.cy + Math.sin(currentAngle) * currentRadius;

    // Opacity based on expansion to hide them when bunching at center
    const opacity = interpolate(expandProgress, [0, 0.15], [0, 1], {
        extrapolateRight: "clamp"
    });

    return { ...node, x, y, scale, opacity, currentRadius };
  });

  // 3. Lines Calculation
  const lines = useMemo(() => {
    const linesToDraw: React.ReactNode[] = [];
    
    // Global line fade in
    const globalLineOpacity = interpolate(frame, [expansionStartFrame + 10, expansionStartFrame + 40], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp"
    });

    for (let i = 0; i < animatedNodes.length; i++) {
      const n1 = animatedNodes[i];
      
      // Skip if node is invisible
      if (n1.opacity < 0.1) continue;

      // Connect to other nodes
      for (let j = i + 1; j < animatedNodes.length; j++) {
        const n2 = animatedNodes[j];
        if (n2.opacity < 0.1) continue;

        const dx = n1.x - n2.x;
        const dy = n1.y - n2.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < connectionDistance) {
          const distFactor = 1 - dist / connectionDistance;
          // Fade lines near center to avoid clutter
          const centerDistMask = Math.min(n1.currentRadius, n2.currentRadius) < 50 ? 0 : 1;
          
          const opacity = distFactor * 0.4 * globalLineOpacity * centerDistMask;

          if (opacity > 0.01) {
             linesToDraw.push(
               <line
                 key={`line-${n1.id}-${n2.id}`}
                 x1={n1.x}
                 y1={n1.y}
                 x2={n2.x}
                 y2={n2.y}
                 stroke={lineColor}
                 strokeWidth={1}
                 strokeOpacity={opacity}
                 strokeLinecap="round"
               />
             );
          }
        }
      }

      // Explicit connection to Center (Title)
      // Only draw if node is far enough away
      if (n1.currentRadius > 80) {
          const centerOpacity = (1 - (n1.currentRadius / (Math.min(width, height) * 0.6))) * globalLineOpacity * 0.2;
          if (centerOpacity > 0.01) {
            linesToDraw.push(
                <line
                    key={`center-${n1.id}`}
                    x1={width/2}
                    y1={height/2}
                    x2={n1.x}
                    y2={n1.y}
                    stroke={lineColor}
                    strokeWidth={1}
                    strokeOpacity={centerOpacity}
                    strokeDasharray="4 4"
                />
            )
          }
      }
    }
    return linesToDraw;
  }, [animatedNodes, connectionDistance, lineColor, frame, expansionStartFrame, width, height]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Montserrat, sans-serif",
        overflow: "hidden",
      }}
    >
      {/* Central Element (Person Icon Start) */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 30,
        }}
      >
        <div
          style={{
            transform: `scale(${titleScale})`,
            opacity: titleOpacity,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: "10px",
          }}
        >
          {/* Main User Icon */}
          <div
            style={{
              padding: "20px",
              background: backgroundColor,
              border: `2px solid ${nodeColor}`,
              borderRadius: "50%",
              boxShadow: `0 0 40px ${nodeColor}40`,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              position: "relative",
            }}
          >
            <svg
              width="48"
              height="48"
              viewBox="0 0 24 24"
              fill="none"
              stroke={titleColor}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
              <circle cx="12" cy="7" r="4" />
            </svg>
            
            {/* Pulse effect ring */}
            <div style={{
                position: "absolute",
                top: -5, left: -5, right: -5, bottom: -5,
                border: `1px solid ${lineColor}`,
                borderRadius: "50%",
                opacity: 0.5,
                transform: `scale(${1 + Math.sin(frame * 0.1) * 0.05})`
            }}/>
          </div>

          <div
            style={{
              color: titleColor,
              fontSize: 20,
              fontWeight: 700,
              letterSpacing: "1px",
              background: backgroundColor,
              padding: "4px 12px",
              borderRadius: "12px",
              opacity: titleOpacity,
            }}
          >
            {titleText}
          </div>
        </div>
      </AbsoluteFill>

      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, zIndex: 10 }}
      >
        {/* Lines Layer */}
        {lines}

        {/* Nodes Layer: People Icons */}
        {animatedNodes.map((node) => {
           // Base scale from props multiplied by animation scale
           // nodeSize prop (e.g. 8) * 3 = 24px default icon size
           const iconSize = nodeSize * 3 * node.sizeVar;
           
           return (
            <svg
              key={node.id}
              x={node.x - iconSize / 2}
              y={node.y - iconSize / 2}
              width={iconSize}
              height={iconSize}
              viewBox="0 0 24 24"
              style={{
                  overflow: "visible", 
                  opacity: node.opacity,
                  transformBox: "fill-box",
                  transformOrigin: "center",
                  // Apply spring scale directly via style for smoothness
                  transform: `scale(${node.scale})`
              }}
            >
                {/* Background glow to hide lines behind icons */}
                <circle cx="12" cy="12" r="10" fill={backgroundColor} opacity={0.8} />

                {/* Person Icon Path */}
                <g 
                    stroke={nodeColor} 
                    strokeWidth="2" 
                    strokeLinecap="round" 
                    strokeLinejoin="round" 
                    fill="none"
                >
                    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                    <circle cx="12" cy="7" r="4" />
                </g>
            </svg>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default ConnectedNetwork;